/**
 * Opt-in Chromium benchmark and end-to-end verification for multi-million-row
 * allele tables. Off unless `LARGE_E2E_DIR` points to a folder generated by
 * `scripts/generate-large-tables.mjs`:
 *
 *   node scripts/generate-large-tables.mjs /tmp/big --rows 2000000
 *   LARGE_E2E_DIR=/tmp/big E2E_PORT=4393 pnpm e2e large-allele-table
 *
 * Measures peak JS heap (Web Worker + page via CDP) and Chromium process-tree
 * RSS (from `ps`) while uploading, building, validating and downloading a
 * `.json.gz` PMO, then stream-decompresses the download to check valid JSON.
 */
import { execFile } from "node:child_process";
import { createReadStream, statSync } from "node:fs";
import { join } from "node:path";
import { promisify } from "node:util";
import { createGunzip } from "node:zlib";

import type { Browser, CDPSession, Page } from "@playwright/test";

import { expect, test } from "./fixtures/privacy";
import { downloadFrom, openStep, verdictCard } from "./support/review";

const execFileAsync = promisify(execFile);

const LARGE_DIR = process.env["LARGE_E2E_DIR"] ?? "";
const MB = 1_048_576;
const LARGE_TIMEOUT = 600_000;
const SAMPLE_INTERVAL_MS = 250;

interface MemoryPeaks {
  peakWorkerHeapUsedMb: number;
  peakWorkerHeapTotalMb: number;
  peakPageHeapUsedMb: number;
  peakPageHeapTotalMb: number;
  peakChromiumRssMb: number;
  samples: number;
}

interface TargetRpc {
  readonly sessionId: string;
  readonly send: (method: string, params?: Record<string, unknown>) => Promise<unknown>;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function metricValue(
  metrics: readonly { readonly name: string; readonly value: number }[],
  name: string,
): number {
  return metrics.find((entry) => entry.name === name)?.value ?? 0;
}

/** Reads total RSS in bytes for the given OS PIDs via `ps`. */
async function rssBytesForPids(pids: readonly number[]): Promise<number> {
  if (pids.length === 0) return 0;
  try {
    const { stdout } = await execFileAsync("ps", ["-o", "rss=", "-p", pids.join(",")]);
    let totalKiB = 0;
    for (const line of stdout.split("\n")) {
      const kib = Number.parseInt(line.trim(), 10);
      if (!Number.isNaN(kib) && kib > 0) totalKiB += kib;
    }
    return totalKiB * 1024;
  } catch {
    return 0;
  }
}

/**
 * Starts a ~250 ms sampler measuring:
 * - Page JS heap via `Performance.getMetrics`,
 * - Attached Web Worker JS heap via CDP `Target.setAutoAttach` + `Performance.getMetrics`
 *   (falling back to `Runtime.getHeapUsage` if a Chromium build omits worker Performance metrics),
 * - Whole Chromium process-tree RSS via `SystemInfo.getProcessInfo` + `ps`.
 */
async function startMemoryMonitor(
  browser: Browser,
  page: Page,
): Promise<{ readonly stop: () => Promise<MemoryPeaks> }> {
  const browserCdp = await browser.newBrowserCDPSession();
  const pageCdp: CDPSession = await page.context().newCDPSession(page);
  await pageCdp.send("Performance.enable");

  const workers = new Map<string, TargetRpc>();
  let nextRpcId = 1;
  const pending = new Map<
    string,
    { readonly resolve: (value: unknown) => void; readonly reject: (error: Error) => void }
  >();

  pageCdp.on("Target.receivedMessageFromTarget", (event) => {
    let parsed: unknown;
    try {
      parsed = JSON.parse(event.message);
    } catch {
      return;
    }
    if (!isRecord(parsed) || typeof parsed["id"] !== "number") return;
    const key = `${event.sessionId}:${parsed["id"]}`;
    const waiter = pending.get(key);
    if (waiter === undefined) return;
    pending.delete(key);
    if (isRecord(parsed["error"])) {
      const msg =
        typeof parsed["error"]["message"] === "string" ? parsed["error"]["message"] : "CDP error";
      waiter.reject(new Error(msg));
    } else {
      waiter.resolve(parsed["result"]);
    }
  });

  const makeWorkerRpc = (sessionId: string): TargetRpc => ({
    sessionId,
    send: async (method, params = {}) => {
      const id = nextRpcId;
      nextRpcId += 1;
      const key = `${sessionId}:${id}`;
      return new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
          pending.delete(key);
          reject(new Error(`CDP timeout: ${method}`));
        }, 2_000);
        pending.set(key, {
          resolve: (value) => {
            clearTimeout(timer);
            resolve(value);
          },
          reject: (error) => {
            clearTimeout(timer);
            reject(error);
          },
        });
        void pageCdp
          .send("Target.sendMessageToTarget", {
            sessionId,
            message: JSON.stringify({ id, method, params }),
          })
          .catch((error: unknown) => {
            clearTimeout(timer);
            pending.delete(key);
            reject(error instanceof Error ? error : new Error(String(error)));
          });
      });
    },
  });

  pageCdp.on("Target.attachedToTarget", (event) => {
    if (event.targetInfo.type === "worker") {
      const rpc = makeWorkerRpc(event.sessionId);
      workers.set(event.sessionId, rpc);
      void rpc.send("Performance.enable").catch(() => undefined);
    }
  });

  pageCdp.on("Target.detachedFromTarget", (event) => {
    workers.delete(event.sessionId);
  });

  await pageCdp.send("Target.setAutoAttach", {
    autoAttach: true,
    waitForDebuggerOnStart: false,
    flatten: false,
  });

  const peaks: MemoryPeaks = {
    peakWorkerHeapUsedMb: 0,
    peakWorkerHeapTotalMb: 0,
    peakPageHeapUsedMb: 0,
    peakPageHeapTotalMb: 0,
    peakChromiumRssMb: 0,
    samples: 0,
  };

  let running = true;
  let inFlight: Promise<void> | null = null;

  const sampleOnce = async (): Promise<void> => {
    try {
      const pageMetrics = await pageCdp.send("Performance.getMetrics");
      const pageUsedMb = metricValue(pageMetrics.metrics, "JSHeapUsedSize") / MB;
      const pageTotalMb = metricValue(pageMetrics.metrics, "JSHeapTotalSize") / MB;
      if (pageUsedMb > peaks.peakPageHeapUsedMb) peaks.peakPageHeapUsedMb = pageUsedMb;
      if (pageTotalMb > peaks.peakPageHeapTotalMb) peaks.peakPageHeapTotalMb = pageTotalMb;
    } catch {
      // Page may be closing or navigating.
    }

    let workerUsedTotal = 0;
    let workerHeapTotal = 0;
    for (const worker of workers.values()) {
      try {
        // oxlint-disable-next-line no-await-in-loop -- small worker count (typically 1)
        const result = await worker.send("Performance.getMetrics");
        if (isRecord(result) && Array.isArray(result["metrics"])) {
          const metrics = result["metrics"].filter(
            (entry): entry is { readonly name: string; readonly value: number } =>
              isRecord(entry) &&
              typeof entry["name"] === "string" &&
              typeof entry["value"] === "number",
          );
          const used = metricValue(metrics, "JSHeapUsedSize");
          const total = metricValue(metrics, "JSHeapTotalSize");
          if (used > 0 || total > 0) {
            workerUsedTotal += used;
            workerHeapTotal += total;
            continue;
          }
        }
      } catch {
        // Fall through to Runtime.getHeapUsage.
      }
      try {
        // oxlint-disable-next-line no-await-in-loop -- fallback for worker heap metrics
        const usage = await worker.send("Runtime.getHeapUsage");
        if (isRecord(usage)) {
          if (typeof usage["usedSize"] === "number") workerUsedTotal += usage["usedSize"];
          if (typeof usage["totalSize"] === "number") workerHeapTotal += usage["totalSize"];
        }
      } catch {
        // Worker may be busy or detached.
      }
    }
    const workerUsedMb = workerUsedTotal / MB;
    const workerTotalMb = workerHeapTotal / MB;
    if (workerUsedMb > peaks.peakWorkerHeapUsedMb) peaks.peakWorkerHeapUsedMb = workerUsedMb;
    if (workerTotalMb > peaks.peakWorkerHeapTotalMb) peaks.peakWorkerHeapTotalMb = workerTotalMb;

    try {
      const info = await browserCdp.send("SystemInfo.getProcessInfo");
      const pids = info.processInfo.map((proc) => proc.id).filter((id) => id > 0);
      const rssMb = (await rssBytesForPids(pids)) / MB;
      if (rssMb > peaks.peakChromiumRssMb) peaks.peakChromiumRssMb = rssMb;
    } catch {
      // Process info unavailable during shutdown.
    }

    peaks.samples += 1;
  };

  const timer = setInterval(() => {
    if (!running || inFlight !== null) return;
    inFlight = sampleOnce().finally(() => {
      inFlight = null;
    });
  }, SAMPLE_INTERVAL_MS);

  return {
    async stop(): Promise<MemoryPeaks> {
      running = false;
      clearInterval(timer);
      if (inFlight !== null) await inFlight;
      await sampleOnce();
      await pageCdp.detach().catch(() => undefined);
      await browserCdp.detach().catch(() => undefined);
      return {
        peakWorkerHeapUsedMb: Math.round(peaks.peakWorkerHeapUsedMb),
        peakWorkerHeapTotalMb: Math.round(peaks.peakWorkerHeapTotalMb),
        peakPageHeapUsedMb: Math.round(peaks.peakPageHeapUsedMb),
        peakPageHeapTotalMb: Math.round(peaks.peakPageHeapTotalMb),
        peakChromiumRssMb: Math.round(peaks.peakChromiumRssMb),
        samples: peaks.samples,
      };
    },
  };
}

/**
 * Stream-decompresses a `.json.gz` file through `zlib.createGunzip()`, checking
 * the gzip magic bytes, counting unpacked UTF-8 JSON bytes, and verifying the
 * stream begins with `{` and ends with `}` without holding the JSON string whole.
 */
async function verifyGzippedJsonStream(filePath: string): Promise<{
  readonly gzBytes: number;
  readonly jsonBytes: number;
  readonly startsWithBrace: boolean;
  readonly endsWithBrace: boolean;
}> {
  const gzBytes = statSync(filePath).size;
  let jsonBytes = 0;
  let firstNonSpace: string | null = null;
  let lastNonSpace: string | null = null;

  const gunzip = createGunzip();
  const stream = createReadStream(filePath).pipe(gunzip);
  for await (const chunk of stream) {
    const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    jsonBytes += buf.byteLength;
    if (firstNonSpace === null) {
      const trimmedStart = buf.toString("utf8", 0, Math.min(buf.byteLength, 64)).trimStart();
      if (trimmedStart.length > 0) firstNonSpace = trimmedStart[0] ?? null;
    }
    const tailStart = Math.max(0, buf.byteLength - 64);
    const trimmedEnd = buf.toString("utf8", tailStart).trimEnd();
    if (trimmedEnd.length > 0) lastNonSpace = trimmedEnd.at(-1) ?? null;
  }

  return {
    gzBytes,
    jsonBytes,
    startsWithBrace: firstNonSpace === "{",
    endsWithBrace: lastNonSpace === "}",
  };
}

test.describe("large allele table", () => {
  test.skip(LARGE_DIR === "", "Set LARGE_E2E_DIR to a generated large-tables folder to run.");

  test("imports, builds, validates and downloads a large allele table as .json.gz", async ({
    browser,
    page,
  }) => {
    test.setTimeout(LARGE_TIMEOUT);

    const allelePath = join(LARGE_DIR, "large_allele_table.csv");
    const panelPath = join(LARGE_DIR, "large_panel_table.csv");
    const metadataPath = join(LARGE_DIR, "large_metadata_table.tsv");
    const csvMb = +(statSync(allelePath).size / MB).toFixed(1);

    const monitor = await startMemoryMonitor(browser, page);
    const started = performance.now();

    try {
      // 1. Microhaplotypes: upload the large allele table and verify matching + preview work.
      await page.goto("/#/build/microhaplotypes");
      await expect(page.getByRole("heading", { level: 1, name: "Microhaplotypes" })).toBeVisible();
      await page.getByLabel("Choose allele table file").setInputFiles(allelePath);
      await expect(page.getByRole("heading", { name: "Match columns" })).toBeVisible({
        timeout: LARGE_TIMEOUT,
      });
      await expect(page.getByText("4 of 4 required fields matched")).toBeVisible({
        timeout: LARGE_TIMEOUT,
      });
      await expect(page.getByRole("button", { name: /Preview/ })).toBeVisible();

      const mhapResult = page.getByRole("region", { name: "Result" });
      await expect(mhapResult.getByText("Ready", { exact: true })).toBeVisible({
        timeout: LARGE_TIMEOUT,
      });
      const rowsText = await mhapResult
        .getByText("Rows read", { exact: true })
        .locator("xpath=following-sibling::span[1]")
        .innerText();
      const rows = Number.parseInt(rowsText.replaceAll(/[^\d]/g, ""), 10);

      // 2. Panel: upload panel table and name it.
      await openStep(page, "Panel");
      await page.getByLabel("Choose target table file").setInputFiles(panelPath);
      await page.getByRole("textbox", { name: "Panel name" }).fill("Mad4hatter");
      await expect(
        page.getByRole("region", { name: "Result" }).getByText("Ready", { exact: true }),
      ).toBeVisible({ timeout: LARGE_TIMEOUT });

      // 3. Specimens: upload metadata table.
      await openStep(page, "Specimens");
      await page.getByLabel("Choose specimen table file").setInputFiles(metadataPath);
      await expect(
        page.getByRole("region", { name: "Result" }).getByText("Ready", { exact: true }),
      ).toBeVisible({ timeout: LARGE_TIMEOUT });

      // 4. Library samples: upload metadata table.
      await openStep(page, "Library samples");
      await page.getByLabel("Choose library sample table file").setInputFiles(metadataPath);
      await expect(
        page.getByRole("region", { name: "Result" }).getByText("Ready", { exact: true }),
      ).toBeVisible({ timeout: LARGE_TIMEOUT });

      // 5. Review: wait for valid verdict and trigger .json.gz download.
      await openStep(page, "Review and download");
      const verdict = verdictCard(page);
      const downloadButton = verdict.getByRole("button", { name: "Download PMO" });
      await expect(verdict.getByRole("heading", { name: /^Ready/ })).toBeVisible({
        timeout: LARGE_TIMEOUT,
      });
      await expect(downloadButton).toBeVisible({ timeout: LARGE_TIMEOUT });
      await expect(verdict.getByText("This file does not match the PMO format")).toHaveCount(0);

      const download = await downloadFrom(page, downloadButton);
      const downloadPath = await download.path();
      expect(downloadPath, "downloaded file path").not.toBeNull();
      expect(download.suggestedFilename()).toMatch(/\.pmo\.json\.gz$/);

      const elapsedMs = Math.round(performance.now() - started);
      const peaks = await monitor.stop();

      const checked = await verifyGzippedJsonStream(downloadPath ?? "");
      expect(checked.gzBytes).toBeGreaterThan(0);
      expect(checked.jsonBytes).toBeGreaterThan(checked.gzBytes);
      expect(checked.startsWithBrace).toBe(true);
      expect(checked.endsWithBrace).toBe(true);

      const summary = {
        rows,
        csvMb,
        elapsedMs,
        peakWorkerHeapMb: peaks.peakWorkerHeapUsedMb,
        peakWorkerHeapTotalMb: peaks.peakWorkerHeapTotalMb,
        peakPageHeapMb: peaks.peakPageHeapUsedMb,
        peakChromiumRssMb: peaks.peakChromiumRssMb,
        samples: peaks.samples,
        gzMb: +(checked.gzBytes / MB).toFixed(1),
        jsonMb: +(checked.jsonBytes / MB).toFixed(1),
        valid: true,
      };
      console.log(`LARGE_E2E_SUMMARY ${JSON.stringify(summary)}`);
    } catch (error) {
      await monitor.stop().catch(() => undefined);
      throw error;
    }
  });
});
